use genex::prelude::*;

pub fn wire(game: &mut Game<super::World>) {
    game.on_ui(|sim, ui, _ctx| {
        let world = &mut sim.world;
        ui.label(format!("Score {}", world.score));
        if ui.add_enabled(world.score > 0, egui::Button::new("Buy bait")).clicked() {
            world.score -= 1;
            world.bait += 1;
        }
    });
}
